1	{
2	  "application": "data-visualization",
3	  "case_id": "case-climate-energy-transition-dual-timeline",
4	  "language": "en",
5	  "style": {
6	    "theme": "editorial",
7	    "audience": "researchers and policy makers",
8	    "tone": "authoritative, data-dense, publication-ready"
9	  },
10	  "goal": [
11	    {
12	      "id": "dual-track-narrative",
13	      "insight": "Present two parallel timelines — fossil energy retirement events on one track and clean energy milestones on the other — so the viewer can visually trace the acceleration of both tracks converging toward an energy transition"
14	    },
15	    {
16	      "id": "encoding-mapping",
17	      "insight": "Encode each event as a marker on a horizontal timeline axis (x=year), with vertical position separating fossil (below) from clean (above), marker size mapped to event significance score, marker color mapped to energy sub-type (coal/oil/gas vs solar/wind/hydrogen), and an overlaid area or line showing global electricity generation share by clean energy"
18	    },
19	    {
20	      "id": "crossover-inflection",
21	      "insight": "Visually highlight the period around 2015–2025 where clean energy milestones densify and fossil retirement events accelerate, making the inflection zone prominent"
22	    },
23	    {
24	      "id": "generation-share-overlay",
25	      "insight": "Show the rising clean energy generation share as a continuous overlay so viewers can connect discrete milestone events to the aggregate shift in electricity mix"
26	    },
27	    {
28	      "id": "sub-type-differentiation",
29	      "insight": "Ensure coal, oil, gas, solar, wind, and hydrogen events are visually distinguishable by color so viewers can identify which sub-sectors lead the transition on each track"
30	    }
31	  ]
32	}

