    {
      "id": "crossover-inflection",
      "insight": "Visually highlight the period around 2015–2025 where clean energy milestones densify and fossil retirement events accelerate, making the inflection zone prominent"
    },
    {
      "id": "generation-share-overlay",
      "insight": "Show the rising clean energy generation share as a continuous overlay so viewers can connect discrete milestone events to the aggregate shift in electricity mix"
    },
    {
      "id": "sub-type-differentiation",
      "insight": "Ensure coal, oil, gas, solar, wind, and hydrogen events are visually distinguishable by color so viewers can identify which sub-sectors lead the transition on each track"
    }
  ]
}

