const fs = require('fs');
const path = require('path');

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
  background: #fefefe;
  color: #1a1a2e;
  padding: 24px;
}
.chart-container {
  width: 1200px;
  height: 700px;
}
h1 {
  font-size: 22px;
  font-weight: 600;
  color: #1a1a2e;
  margin-bottom: 4px;
}
.subtitle {
  font-size: 13px;
  color: #666;
  margin-bottom: 20px;
}
.legend-container {
  display: flex;
  gap: 32px;
  margin-bottom: 16px;
  font-size: 11px;
}
.legend-section { display: flex; flex-direction: column; gap: 6px; }
.legend-section h3 { font-size: 10px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 2px; }
.legend-items { display: flex; gap: 12px; flex-wrap: wrap; }
.legend-item { display: flex; align-items: center; gap: 5px; }
.legend-dot { width: 10px; height: 10px; border-radius: 50%; }
.legend-line { width: 20px; height: 3px; border-radius: 2px; }
svg { display: block; }
.axis-label { font-size: 11px; fill: #666; }
.title-label { font-size: 10px; fill: #999; }
.event-label { font-size: 8px; fill: #333; pointer-events: none; }
.grid line { stroke: #e5e5e5; stroke-dasharray: 2,2; }
.grid .domain { stroke: none; }
</style>
</head>
<body>
<div class="chart-container">
  <h1>Global Energy Transition: Dual-Track Timeline (2001–2025)</h1>
  <div class="subtitle">Fossil retirement events and clean energy milestones with clean electricity generation share</div>
  <div class="legend-container">
    <div class="legend-section">
      <h3>Clean Energy Track</h3>
      <div class="legend-items">
        <div class="legend-item"><div class="legend-dot" style="background:#e67e22"></div>Solar</div>
        <div class="legend-item"><div class="legend-dot" style="background:#3498db"></div>Wind</div>
        <div class="legend-item"><div class="legend-dot" style="background:#27ae60"></div>Hydrogen</div>
      </div>
    </div>
    <div class="legend-section">
      <h3>Fossil Track</h3>
      <div class="legend-items">
        <div class="legend-item"><div class="legend-dot" style="background:#c0392b"></div>Coal</div>
        <div class="legend-item"><div class="legend-dot" style="background:#8e44ad"></div>Oil</div>
        <div class="legend-item"><div class="legend-dot" style="background:#d35400"></div>Gas</div>
      </div>
    </div>
    <div class="legend-section">
      <h3>Significance</h3>
      <div class="legend-items">
        <div class="legend-item"><div class="legend-dot" style="width:8px;height:8px;background:#666"></div>Low (3–4)</div>
        <div class="legend-item"><div class="legend-dot" style="width:12px;height:12px;background:#666"></div>Medium (5–6)</div>
        <div class="legend-item"><div class="legend-dot" style="width:16px;height:16px;background:#666"></div>High (7–9)</div>
      </div>
    </div>
    <div class="legend-section">
      <h3>Generation Share</h3>
      <div class="legend-items">
        <div class="legend-item"><div class="legend-line" style="background:linear-gradient(to right, #2ecc71, #27ae60)"></div>Clean Energy %</div>
      </div>
    </div>
  </div>
  <svg id="chart"></svg>
</div>
<script src="https://cdn.jsdelivr.net/npm/d3@7/dist/d3.min.js"></script>
<script>
const events = [{"year":2001,"track":"clean","sub_type":"solar","event":"First commercial 1 MW thin-film solar plant (Germany)","significance":3},{"year":2002,"track":"fossil","sub_type":"coal","event":"UK announces coal phase-down roadmap","significance":4},{"year":2003,"track":"clean","sub_type":"wind","event":"Denmark's Horns Rev 1 offshore wind farm (160 MW)","significance":5},{"year":2005,"track":"fossil","sub_type":"oil","event":"IEA warns of conventional oil plateau","significance":4},{"year":2006,"track":"clean","sub_type":"solar","event":"Solar PV crosses 1 GW annual global installations","significance":5},{"year":2007,"track":"fossil","sub_type":"coal","event":"Ontario begins coal plant closures","significance":5},{"year":2009,"track":"clean","sub_type":"wind","event":"Global wind capacity surpasses 150 GW","significance":5},{"year":2010,"track":"fossil","sub_type":"gas","event":"US shale gas boom sparks methane leakage debate","significance":4},{"year":2011,"track":"clean","sub_type":"solar","event":"Solar PV cost falls below $1/W for first time","significance":7},{"year":2012,"track":"fossil","sub_type":"coal","event":"US coal generation drops below 40% for first time","significance":6},{"year":2013,"track":"clean","sub_type":"wind","event":"London Array becomes world's largest offshore wind farm (630 MW)","significance":6},{"year":2014,"track":"fossil","sub_type":"oil","event":"Oil price crash signals demand uncertainty","significance":5},{"year":2015,"track":"clean","sub_type":"solar","event":"Global solar PV cumulative capacity exceeds 200 GW","significance":7},{"year":2015,"track":"fossil","sub_type":"coal","event":"China announces moratorium on new coal mine approvals","significance":8},{"year":2016,"track":"clean","sub_type":"wind","event":"Offshore wind auction prices fall below €50/MWh","significance":6},{"year":2016,"track":"fossil","sub_type":"coal","event":"UK goes first full day without coal power since 1882","significance":7},{"year":2017,"track":"clean","sub_type":"solar","event":"India's 648 MW Kamuthi solar plant completed","significance":5},{"year":2017,"track":"fossil","sub_type":"gas","event":"EU proposes methane regulation for gas infrastructure","significance":4},{"year":2018,"track":"clean","sub_type":"wind","event":"Global offshore wind capacity exceeds 20 GW","significance":6},{"year":2018,"track":"fossil","sub_type":"coal","event":"Germany's Coal Commission recommends 2038 exit","significance":7},{"year":2019,"track":"clean","sub_type":"hydrogen","event":"Japan launches Hydrogen Strategy, first green H2 pilot","significance":5},{"year":2019,"track":"fossil","sub_type":"oil","event":"Global oil demand growth slows to decade low","significance":5},{"year":2020,"track":"clean","sub_type":"solar","event":"Solar becomes cheapest electricity source in history (IEA)","significance":9},{"year":2020,"track":"fossil","sub_type":"coal","event":"COVID-19 accelerates coal plant retirements globally","significance":8},{"year":2020,"track":"clean","sub_type":"wind","event":"UK Dogger Bank approved as world's largest offshore wind (3.6 GW)","significance":7},{"year":2021,"track":"fossil","sub_type":"gas","event":"IEA Net Zero report: no new gas fields needed after 2021","significance":8},{"year":2021,"track":"clean","sub_type":"hydrogen","event":"EU Hydrogen Strategy targets 40 GW electrolyzer by 2030","significance":6},{"year":2022,"track":"clean","sub_type":"solar","event":"Global solar annual additions exceed 200 GW","significance":8},{"year":2022,"track":"fossil","sub_type":"coal","event":"G7 pledges to end unabated coal power by 2035","significance":8},{"year":2022,"track":"fossil","sub_type":"gas","event":"EU energy crisis revives LNG debate vs renewables","significance":7},{"year":2023,"track":"clean","sub_type":"wind","event":"China installs record 20 GW offshore wind in single year","significance":8},{"year":2023,"track":"clean","sub_type":"hydrogen","event":"NEOM green hydrogen mega-project breaks ground (Saudi Arabia)","significance":7},{"year":2023,"track":"fossil","sub_type":"oil","event":"IEA declares peak oil demand expected before 2030","significance":9},{"year":2024,"track":"clean","sub_type":"solar","event":"Solar PV surpasses 2 TW cumulative global capacity","significance":9},{"year":2024,"track":"fossil","sub_type":"coal","event":"India retires first wave of subcritical coal plants","significance":6},{"year":2025,"track":"clean","sub_type":"hydrogen","event":"First commercial-scale green hydrogen export terminal operational","significance":7},{"year":2025,"track":"fossil","sub_type":"gas","event":"Major pension funds divest from new gas exploration","significance":6}];
const generationShare = [{"year":2000,"clean_share_pct":19.2},{"year":2002,"clean_share_pct":19.5},{"year":2004,"clean_share_pct":19.8},{"year":2006,"clean_share_pct":20.3},{"year":2008,"clean_share_pct":20.9},{"year":2010,"clean_share_pct":21.7},{"year":2012,"clean_share_pct":23.1},{"year":2014,"clean_share_pct":24.8},{"year":2015,"clean_share_pct":25.6},{"year":2016,"clean_share_pct":26.5},{"year":2017,"clean_share_pct":27.4},{"year":2018,"clean_share_pct":28.6},{"year":2019,"clean_share_pct":29.8},{"year":2020,"clean_share_pct":31.5},{"year":2021,"clean_share_pct":32.8},{"year":2022,"clean_share_pct":34.6},{"year":2023,"clean_share_pct":37.2},{"year":2024,"clean_share_pct":39.8},{"year":2025,"clean_share_pct":42.0},{"year":2027,"clean_share_pct":46.5},{"year":2030,"clean_share_pct":52.0},{"year":2033,"clean_share_pct":57.5},{"year":2035,"clean_share_pct":62.0}];
const colorMap = {solar:'#e67e22',wind:'#3498db',hydrogen:'#27ae60',coal:'#c0392b',oil:'#8e44ad',gas:'#d35400'};
const sizeScale = d3.scaleLinear().domain([3,9]).range([6,16]);
const svg = d3.select('#chart').attr('width',1200).attr('height',560);
const margin = {top:30,right:60,bottom:50,left:60};
const width = 1200 - margin.left - margin.right;
const height = 560 - margin.top - margin.bottom;
const g = svg.append('g').attr('transform','translate('+margin.left+','+margin.top+')');
const xScale = d3.scaleLinear().domain([2000,2030]).range([0,width]);
const yClean = height * 0.35;
const yFossil = height * 0.75;
const centerY = height * 0.55;
// Clean energy share area
const xGen = d3.scaleLinear().domain([2000,2035]).range([0,width]);
const yGen = d3.scaleLinear().domain([15,65]).range([height * 0.5, 20]);
const area = d3.area().x(d=>xGen(d.year)).y0(height * 0.5).y1(d=>yGen(d.clean_share_pct)).curve(d3.curveMonotoneX);
const line = d3.line().x(d=>xGen(d.year)).y(d=>yGen(d.clean_share_pct)).curve(d3.curveMonotoneX);
g.append('path').datum(generationShare).attr('d',area).attr('fill','#2ecc71').attr('fill-opacity',0.15);
g.append('path').datum(generationShare).attr('d',line).attr('stroke','#27ae60').attr('stroke-width',2.5).attr('fill','none');
// Y axis labels
g.append('text').attr('class','axis-label').attr('x',-10).attr('y',yClean+4).attr('text-anchor','end').text('CLEAN ENERGY').attr('fill','#27ae60').attr('font-weight','600');
g.append('text').attr('class','axis-label').attr('x',-10).attr('y',yFossil+4).attr('text-anchor','end').text('FOSSIL FUEL').attr('fill','#c0392b').attr('font-weight','600');
// Track lines
g.append('line').attr('x1',0).attr('x2',width).attr('y1',yClean).attr('y2',yClean).attr('stroke','#ddd').attr('stroke-width',1).attr('stroke-dasharray','4,4');
g.append('line').attr('x1',0).attr('x2',width).attr('y1',yFossil).attr('y2',yFossil).attr('stroke','#ddd').attr('stroke-width',1).attr('stroke-dasharray','4,4');
// Grid lines
const xTicks = [2000,2005,2010,2015,2020,2025,2030];
xTicks.forEach(t => {
  g.append('line').attr('class','grid').attr('x1',xScale(t)).attr('x2',xScale(t)).attr('y1',0).attr('y2',height).attr('stroke','#eee').attr('stroke-width',1);
});
// X Axis
g.append('g').attr('transform','translate(0,'+height+')').call(d3.axisBottom(xScale).tickValues(xTicks).tickFormat(d3.format('d'))).select('.domain').attr('stroke','#ddd');
g.selectAll('.tick line').attr('stroke','#ddd');
g.selectAll('.tick text').attr('class','axis-label').attr('font-size','11px');
// Inflection zone 2015-2025
g.append('rect').attr('x',xScale(2015)).attr('width',xScale(2025)-xScale(2015)).attr('y',0).attr('height',height).attr('fill','#3498db').attr('fill-opacity',0.04);
g.append('text').attr('x',xScale(2020)).attr('y',height+40).attr('text-anchor','middle').attr('font-size','10px').attr('fill','#3498db').attr('font-style','italic').text('Inflection Zone: Accelerating Transition');
// Events
const tooltip = g.append('g').attr('class','tooltip');
events.forEach(e => {
  const cx = xScale(e.year);
  const cy = e.track === 'clean' ? yClean - 50 : yFossil + 50;
  const r = sizeScale(e.significance);
  const color = colorMap[e.sub_type];
  // Marker
  g.append('circle').attr('cx',cx).attr('cy',cy).attr('r',r).attr('fill',color).attr('fill-opacity',0.8).attr('stroke',color).attr('stroke-width',1.5).attr('stroke-opacity',1);
  // Significance ring
  g.append('circle').attr('cx',cx).attr('cy',cy).attr('r',r+2).attr('fill','none').attr('stroke',color).attr('stroke-width',0.5).attr('stroke-opacity',0.4);
});
// Generation share axis
g.append('g').attr('transform','translate('+width+',0)').call(d3.axisRight(yGen).ticks(5).tickFormat(d=>d+'%')).select('.domain').attr('stroke','#ddd');
g.selectAll('.tick text').attr('class','axis-label').attr('font-size','10px');
g.append('text').attr('transform','rotate(90)').attr('x',width+45).attr('y',-width-10).attr('text-anchor','middle').attr('font-size','10px').attr('fill','#27ae60').text('Clean Generation Share (%)');
// Source
svg.append('text').attr('x',1200-24).attr('y',680).attr('text-anchor','end').attr('font-size','9px').attr('fill','#999').text('Sources: IEA, IRENA, expert assessments. Generation share post-2024 are projections.');
</script>
</body>
</html>`;

(async () => {
